const invoicePaperSizes=[{id:'A4',name:'A4',dimensions:'210 × 297 mm',width:210},{id:'A5',name:'A5',dimensions:'148 × 210 mm',width:148},{id:'Letter',name:'Letter',dimensions:'216 × 279 mm',width:216}];
let activeInvoicePaper='A4';
function supportedInvoicePaper(value){return invoicePaperSizes.some(p=>p.id===value)?value:'A4'}
function applyInvoicePaper(){let sheet=$('#modalBody .invoice');if(!sheet)return;sheet.dataset.paper=activeInvoicePaper;let info=invoicePaperSizes.find(p=>p.id===activeInvoicePaper);sheet.style.setProperty('--invoice-paper-width',(info.width-20)+'mm');$('#modalTitle').textContent=activeInvoicePaper+' Invoice';for(let button of $$('#modalBody .formactions button'))if(button.textContent.includes('Print A4')||button.dataset.fullPaperPrint){button.dataset.fullPaperPrint='';button.textContent='Print '+activeInvoicePaper+' / Save PDF';button.onclick=printA4Invoice}}
const invoiceBeforePaperSizes=invoice;
invoice=function(key,id,paper){activeInvoicePaper=supportedInvoicePaper(paper||db.settings.invoicePaperSize);invoiceBeforePaperSizes(key,id);applyInvoicePaper();let controls=$('#modalBody .invoiceFormatControls');if(controls){let label=document.createElement('label');label.className='invoiceStyleChoice';label.innerHTML=`Paper Size <select id="invoicePaperChoice" aria-label="Invoice paper size">${opts(invoicePaperSizes.map(p=>({value:p.id,label:p.name+' — '+p.dimensions})),activeInvoicePaper)}</select>`;controls.appendChild(label);const choosePaper=value=>{activeInvoicePaper=supportedInvoicePaper(value);applyInvoicePaper();let select=$('#invoicePaperChoice');if(select)select.value=activeInvoicePaper;for(let button of $$('#chooseA4Invoice,#chooseA5Invoice')){let active=(button.id==='chooseA4Invoice'&&activeInvoicePaper==='A4')||(button.id==='chooseA5Invoice'&&activeInvoicePaper==='A5');button.classList.toggle('secondary',!active);button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active))}};$('#invoicePaperChoice').onchange=e=>choosePaper(e.target.value);let full=$('#chooseA4Invoice'),small=$('#chooseA5Invoice');if(full){full.textContent='A4 Invoice';full.onclick=()=>choosePaper('A4')}if(small)small.onclick=()=>choosePaper('A5');choosePaper(activeInvoicePaper)}};
printA4Invoice=function(){clearInvoicePrintMode();let paper=supportedInvoicePaper(activeInvoicePaper),style=document.createElement('style');style.id='a4PageSize';style.textContent='@media print{@page{size:'+paper+' portrait;margin:10mm}body.printingA4 .invoice{max-width:'+(invoicePaperSizes.find(p=>p.id===paper).width-20)+'mm!important}}';document.head.appendChild(style);document.body.classList.add('printingA4');const cleanup=()=>{clearInvoicePrintMode();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);try{window.print()}catch{cleanup();toast('Use your browser print menu.')}};
const settingsBeforePaperSamples=settingsPage;
settingsPage=function(){return settingsBeforePaperSamples()+`<section class="panel"><div class="panelhead"><h2>Invoice Samples by Paper Size</h2></div><div class="panelbody"><p>Preview a saved bill in the actual paper layout. These previews do not change bill amounts or save new invoices.</p><div class="paperSampleGrid">${[...invoicePaperSizes,...[{id:'58',name:'Thermal 58 mm',dimensions:'58 mm roll',width:58},{id:'80',name:'Thermal 80 mm',dimensions:'80 mm roll',width:80}]].map(p=>`<div class="paperSampleCard"><div class="paperSampleMini paper-${p.id}" aria-hidden="true"><b>INVOICE</b><i></i><i></i><i></i><small>TOTAL</small></div><strong>${p.name}</strong><span>${p.dimensions}</span><button type="button" class="btn secondary" data-paper-sample="${p.id}">Preview ${p.name}</button></div>`).join('')}</div><div class="toolbar"><label class="field"><span>Default Full-Page Paper Size</span><select id="defaultInvoicePaper">${opts(invoicePaperSizes.map(p=>({value:p.id,label:p.name+' ('+p.dimensions+')'})),supportedInvoicePaper(db.settings.invoicePaperSize))}</select></label><button type="button" class="btn" id="saveDefaultInvoicePaper">Save Paper Size</button></div><p>Match the same paper size in your printer driver. Thermal roll length depends on invoice content.</p></div></section>`};
const renderBeforePaperSamples=render;
render=function(){renderBeforePaperSamples();if(page!=='settings')return;for(let button of $$('[data-paper-sample]'))button.onclick=()=>{let key=db.jobs.length?'jobs':db.sales.length?'sales':null;if(!key)return toast('Create a job card or sale first to preview a sample.');let id=db[key][0].id,size=button.dataset.paperSample;if(['58','80'].includes(size))openThermalInvoice(key,id,Number(size));else invoice(key,id,size)};if($('#saveDefaultInvoicePaper'))$('#saveDefaultInvoicePaper').onclick=()=>{let previous=db.settings.invoicePaperSize;db.settings.invoicePaperSize=supportedInvoicePaper($('#defaultInvoicePaper').value);if(save('Default paper size saved')===false)db.settings.invoicePaperSize=previous}};
render();
/* Presentation styles are available on full-page and thermal invoices. */
function applyThermalStyle(sheet,style){if(!sheet)return;for(let entry of invoiceStyles)sheet.classList.remove('thermalStyle-'+entry.id);sheet.classList.add('thermalStyle-'+style)}
const thermalBeforeSharedStyles=openThermalInvoice;
openThermalInvoice=function(key,id,width){thermalBeforeSharedStyles(key,id,width);let sheet=$('#modalBody .thermalInvoice'),controls=$('#modalBody .invoiceFormatControls');if(!sheet||!controls)return;let style=selectedInvoiceStyle(key,id);applyThermalStyle(sheet,style);let label=document.createElement('label');label.className='invoiceStyleChoice';label.innerHTML=`Receipt Style <select id="thermalStyleChoice" aria-label="Thermal receipt style">${opts(invoiceStyles.map(s=>({value:s.id,label:s.name})),style)}</select>`;controls.appendChild(label);$('#thermalStyleChoice').onchange=e=>{invoiceStyleOverrides[key+'|'+id]=e.target.value;applyThermalStyle(sheet,e.target.value)}};
const invoiceBeforeUniversalStyleLabel=invoice;
invoice=function(key,id,paper){invoiceBeforeUniversalStyleLabel(key,id,paper);let select=$('#previewInvoiceStyle');if(select&&select.parentElement.firstChild?.nodeType===3)select.parentElement.firstChild.textContent='Invoice Style '};
const settingsBeforeUniversalStyles=settingsPage;
settingsPage=function(){return settingsBeforeUniversalStyles().replaceAll('Choose a default A4 invoice style.','Choose a default invoice style for A4, A5, Letter and 58 / 80 mm thermal receipts.').replaceAll('Use the A4 Style selector inside an invoice to compare styles without changing the saved default. Thermal receipts retain their dedicated 58 / 80 mm layout.','Use Invoice Style or Receipt Style inside a preview to compare Classic, Modern and Compact. Each style adapts to the selected paper size.').replaceAll('Default Full-Page Paper Size','Default Paper Size for Regular Printers')};
render();
